<template>
  <component :is="screenComponent" />
</template>

<script lang="ts">
import { defineComponent } from 'vue';
import { useUserStore } from 'src/store/User/user_details.store';
import { useActiveScreenStore } from 'src/store/Router/active-screen.store';
import { resolveValidationScreen, type ValidationScreen } from './resolveValidationScreen';
import { VALIDATION_SCREENS } from './screens';

export default defineComponent({
  name: 'ValidationDispatcher',
  setup() {
    return { userStore: useUserStore(), activeScreen: useActiveScreenStore() };
  },
  computed: {
    screen(): ValidationScreen {
      return resolveValidationScreen({ isMediUser: this.userStore.isMediUser() });
    },
    screenComponent() {
      return VALIDATION_SCREENS[this.screen];
    },
  },
  watch: {
    screen: {
      immediate: true,
      handler(screen: ValidationScreen) {
        this.activeScreen.setScreen(screen);
      },
    },
  },
  beforeUnmount() {
    if (this.activeScreen.screen === this.screen) this.activeScreen.clear();
  },
});
</script>
